<?php
defined('BASEPATH') or exit('No direct script access allowed');
class Pipeline_documents extends CI_Controller {
 public function __construct(){parent::__construct();is_login();$this->load->library('Pipeline_access');$this->load->model('Pipeline_operation_model','operations');$this->load->library('Pipeline_operation_forms',array(),'operation_forms');$role=$this->Spbb_model->get_role($this->session->userdata('MIS_LOGGED_ID'));if($role['role']==='CUSTOMER')show_error('Perubahan dokumen operasional hanya untuk petugas.',403);if(!$this->db->table_exists('PipelineOperation'))show_error('Jalankan migrasi dokumen operasi terlebih dahulu.',503);if(!$this->session->userdata('pipeline_form_token'))$this->session->set_userdata('pipeline_form_token',bin2hex(random_bytes(24)));}
 private function menu($kind){$map=array('BASTB'=>'bastb','RDT'=>'rdt','PASS'=>'port_pass','spp'=>'spp_ocr','bunker'=>'bunker','ksop'=>'ksop','invoice'=>'invoices');if(!isset($map[$kind]))show_404();$this->pipeline_access->require_menu($map[$kind]);}

 private function system_admin()
 {
  return $this->session->userdata('USER_ROLE')==='SUPERADMIN' || strtolower((string)$this->session->userdata('MIS_LOGGED_ID'))==='admin';
 }

 public function spp_links($id)
 {
  $this->menu('spp');
  $spp=$this->target('spp',$id);
  if(!$spp)show_404();
  $billing=$this->operations->billing;
  $document=$spp['DocumentID']?$billing->document($spp['DocumentID']):null;
  $delivery=$billing->delivery($spp['DeliveryID']?:($document['DeliveryID']??0));
  $orders=$this->db->select('RequestID,RequestNo')->where('CaptureID',(int)$id)->get('PipelineFlowRequest')->result_array();
  $operations=$this->db->select('OperationID,DocumentNo,Kind')->where('CaptureID',(int)$id)->get('PipelineOperation')->result_array();
  $invoices=$this->db->query("SELECT I.InvoiceID,I.InvoiceNumber FROM PipelineInvoice I WHERE
      EXISTS(SELECT 1 FROM PipelineSppInvoice S WHERE S.InvoiceID=I.InvoiceID AND S.CaptureID=?) OR
      EXISTS(SELECT 1 FROM PipelineInvoiceDelivery D WHERE D.InvoiceID=I.InvoiceID AND D.DeliveryID=?)",
      array((int)$id,(int)($delivery['DeliveryID']??0)))->result_array();
  $canDetach=$delivery && !$orders && !$operations && !$invoices && $this->system_admin();
  $revision=hash('sha256',json_encode($spp));
  $this->render('spp_links',compact('spp','document','delivery','orders','operations','invoices','canDetach','revision')+array('judul'=>'Dokumen Terkait SPP'));
 }

 public function detach_spp($id)
 {
  $this->menu('spp');
  if(!$this->system_admin())show_error('Aksi khusus Administrator Sistem.',403);
  $this->guard();
  $spp=$this->target('spp',$id);
  if(!$spp)show_404();
  try{
   $version=$this->input->post('RevisionHash');
   if(!is_string($version)||!hash_equals(hash('sha256',json_encode($spp)),$version))throw new RuntimeException('SPP berubah. Muat ulang halaman.');
   $this->operations->billing->detach_spp($spp);
   $this->session->set_flashdata('Berhasil','Tautan DO dilepas. File dan hasil OCR SPP siap digunakan kembali.');
   redirect('Pipeline_spp/review/'.(int)$id);
  }catch(RuntimeException $e){
   $this->session->set_flashdata('Gagal',$e->getMessage());
   redirect('Pipeline_documents/spp_links/'.(int)$id);
  }
 }
 private function guard(){if($this->input->method()!=='post'||!is_string($this->input->post('pipeline_token'))||!hash_equals($this->session->userdata('pipeline_form_token'),$this->input->post('pipeline_token')))show_error('Form kedaluwarsa.',403);}
 private function render($view,$data){$data+=array('judul'=>'Dokumen Operasional Pipanisasi','pipeline_token'=>$this->session->userdata('pipeline_form_token'),'branches'=>$this->operations->billing->branches());$this->load->view('templates/header',$data);$this->load->view('templates/sidebar');$this->load->view('pipeline/'.$view,$data);$this->load->view('templates/footer');}
 public function index($kind='BASTB'){$this->menu($kind);$rows=$this->operations->rows($kind);$this->render('operation_list',compact('kind','rows'));}
 private function param($name,$post=false){$v=$post?$this->input->post($name):$this->input->get($name);if($v===null||$v==='')return 0;if(!is_string($v)||!ctype_digit($v))throw new InvalidArgumentException('Pilihan sumber tidak valid.');return (int)$v;}
 public function form($kind='BASTB',$id=0){$this->menu($kind);$row=$id?$this->operations->row($id):null;if($id&&(!$row||$row['Kind']!==$kind))show_404();$error='';$form=$row?json_decode($row['Snapshot'],true):array();$links=$row?:array();$post=$this->input->method()==='post';
  try{if($post){$this->guard();$saved=$this->operations->save($kind,$this->input->post(),$id?:null);redirect('Pipeline_documents/print_document/'.$saved);return;}
   if(!$id&&($this->input->get('CaptureID')||$this->input->get('ParentID'))){$source=$this->operations->source($kind,$this->param('CaptureID'),$this->param('VesselID'),$this->param('BunkerID'),$this->param('ParentID'));$form=$source['fields'];$links=$source['links'];}
  }catch(Exception $e){$error=$e->getMessage();if($post)$form=array_merge($form,array_filter($this->input->post(),'is_scalar'));}
  $captures=$this->operations->spp->captures();$vessels=$this->operations->masterdata->vessels();$bunkers=array();$ids=array_column($this->operations->billing->branches(),'SpbbID');if($ids)$bunkers=$this->db->where_in('SpbbID',$ids)->order_by('BunkerID','DESC')->get('PipelineBunker')->result_array();$parents=$this->operations->rows('BASTB');$tariffs=$this->operations->tariffs();$fields=$this->operation_forms->fields($kind);$this->render('operation_form',compact('kind','row','form','links','captures','vessels','bunkers','parents','tariffs','fields','error'));
 }
 public function print_document($id){$row=$this->operations->row($id);if(!$row)show_404();$this->menu($row['Kind']);$s=json_decode($row['Snapshot'],true);$pdf_mode=$this->input->get('pdf')==='1';$data=compact('row','s','pdf_mode');$html=$this->load->view('pipeline/operation_print',$data,true);if(!$pdf_mode){echo $html;return;}require_once FCPATH.'vendor/autoload.php';$temp=sys_get_temp_dir().'/ismartenergy_ver1_pdf';if(!is_dir($temp))mkdir($temp,0700,true);$pdf=new \Mpdf\Mpdf(array('mode'=>'c','format'=>$row['Kind']==='PASS'?'A5-L':'A4','default_font'=>'helvetica','margin_top'=>10,'margin_bottom'=>10,'margin_left'=>15,'margin_right'=>15,'tempDir'=>$temp));$pdf->WriteHTML($html);$pdf->Output($row['Kind'].'-'.$id.'.pdf','D');}
 public function tariffs(){ $this->pipeline_access->require_menu('pass_rates');$error='';if($this->input->method()==='post'){$this->guard();try{$branch=$this->param('SpbbID',true);if(!$this->operations->billing->branch_allowed($branch))throw new RuntimeException('Area di luar akses.');$data=array('SpbbID'=>$branch,'CreatedBy'=>$this->session->userdata('MIS_LOGGED_ID'));foreach(array('VehicleType'=>100,'DecisionNo'=>200,'EffectiveDate'=>10) as $key=>$max){$v=$this->input->post($key);if(!is_string($v)||trim($v)===''||mb_strlen($v)>$max)throw new RuntimeException($key.' wajib diisi.');$data[$key]=trim($v);}if(!$this->pipeline_finance->date_valid($data['EffectiveDate']))throw new RuntimeException('Tanggal tarif tidak valid.');foreach(array('PersonRate','VehicleRate','BerthRate') as $key)$data[$key]=$this->pipeline_finance->number($this->input->post($key));$this->operations->transaction(function()use($data){$this->operations->insert('PipelinePassTariff','PassTariffID',$data);});redirect('Pipeline_documents/tariffs');return;}catch(Exception $e){$error=$e->getMessage();}}$rows=$this->operations->tariffs();$this->render('pass_tariffs',compact('rows','error'));}
 public function invoice($editId=0){ $this->pipeline_access->require_menu('invoices');$error='';$quote=null;$ids=array();$captureIds=array();$input=array('InvoiceNumber'=>'','InvoiceDate'=>date('Y-m-d'),'DueDate'=>date('Y-m-d',strtotime('+7 days')),'Signatory'=>'','SignatoryTitle'=>'AN. GENERAL MANAGER, DEPARTEMENT HEAD BISNIS DAN PELAYANAN');if($editId){$existing=$this->operations->billing->invoice($editId);if(!$existing)show_404();foreach($input as $k=>$v)$input[$k]=$existing[$k];$linked=$this->db->where('InvoiceID',(int)$editId)->get('PipelineOperationInvoice')->result_array();foreach($linked as $link){$doc=$this->operations->row($link['OperationID']);if($doc&&in_array($doc['Kind'],array('BASTB','PASS'),true))$ids[]=(int)$doc['OperationID'];}$captureIds=array_map('intval',array_column($this->db->where('InvoiceID',(int)$editId)->get('PipelineSppInvoice')->result_array(),'CaptureID'));if(!$ids&&!$captureIds)$error='Invoice ini menggunakan alur lama. Edit metadata melalui daftar invoice.';}if($this->input->method()==='post'){$this->guard();$ids=array();try{$raw=$this->input->post('OperationIDs')?:array();if(!is_array($raw)||count($raw)>500)throw new RuntimeException('Pilih dokumen.');foreach($raw as $id){if(!is_string($id)||!ctype_digit($id))throw new RuntimeException('ID dokumen tidak valid.');$ids[]=(int)$id;}$captureIds=array();$rawSpp=$this->input->post('CaptureIDs')?:array();if(!is_array($rawSpp)||count($rawSpp)>500)throw new RuntimeException('Pilihan SPP tidak valid.');foreach($rawSpp as $sppId){if(!is_string($sppId)||!ctype_digit($sppId))throw new RuntimeException('ID SPP tidak valid.');$captureIds[]=(int)$sppId;}foreach($input as $key=>$value){$v=$this->input->post($key);if(!is_string($v)||trim($v)===''||mb_strlen($v)>100)throw new RuntimeException($key.' wajib diisi.');$input[$key]=trim($v);}if(!$this->pipeline_finance->date_valid($input['InvoiceDate'])||!$this->pipeline_finance->date_valid($input['DueDate'])||$input['DueDate']<$input['InvoiceDate'])throw new RuntimeException('Tanggal invoice/jatuh tempo tidak valid.');$quote=$this->operations->quote($ids,$editId?:null,$captureIds);if($this->input->post('action')==='create'){$expected=$this->input->post('QuoteHash');if(!is_string($expected))throw new RuntimeException('Preview ulang.');$id=$this->operations->invoice_create($ids,$input,$expected,$editId?:null,$captureIds);redirect('Pipeline_billing/invoice/'.$id);return;}}catch(Exception $e){$error=$e->getMessage();}}$rows=array_values(array_filter($this->operations->rows(),function($r){return in_array($r['Kind'],array('BASTB','PASS'),true);}));$captures=$this->operations->spp_invoice->candidates($editId?:null);$this->render('operation_invoice',compact('captures','captureIds','rows','quote','ids','input','error','editId'));}

 private function replacement($type){
  if(!in_array($type,array('spp','ksop'),true)||empty($_FILES['ReplacementFile'])||$_FILES['ReplacementFile']['error']===UPLOAD_ERR_NO_FILE)return null;
  $f=$_FILES['ReplacementFile'];if(!is_scalar($f['error'])||(int)$f['error']!==UPLOAD_ERR_OK||$f['size']>15*1024*1024||!is_uploaded_file($f['tmp_name']))throw new RuntimeException('File pengganti maksimal 15 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=array('image/jpeg'=>'jpg','image/png'=>'png','application/pdf'=>'pdf');if(!isset($ext[$mime]))throw new RuntimeException('Pilih JPG, PNG atau PDF.');if($mime==='application/pdf'){if(file_get_contents($f['tmp_name'],false,null,0,5)!=='%PDF-')throw new RuntimeException('PDF tidak valid.');}else{$size=@getimagesize($f['tmp_name']);if(!$size||$size[0]*$size[1]>24000000)throw new RuntimeException('Gambar maksimal 24 megapiksel.');}
  $name=bin2hex(random_bytes(24)).'.'.$ext[$mime];$path=APPPATH.'storage/'.($type==='spp'?'pipeline':'ksop').'/'.$name;if(!is_dir(dirname($path))&&!mkdir(dirname($path),0700,true))throw new RuntimeException('Penyimpanan tidak tersedia.');if(!move_uploaded_file($f['tmp_name'],$path))throw new RuntimeException('File pengganti gagal diunggah.');
  $result=array('path'=>$path,'data'=>array('StoredName'=>$name,'OriginalName'=>mb_substr(basename($f['name']),0,255),'MimeType'=>$mime,'FileHash'=>hash_file('sha256',$path),'FileSize'=>filesize($path)));
  if($type==='spp'){@set_time_limit(90);try{$result['ocr']=$this->pipeline_spp_ocr->read($path);}catch(Exception $e){$result['ocr']=array('fields'=>array_fill_keys(array_keys($this->pipeline_spp_ocr->fields()),''),'warnings'=>array('OCR file pengganti belum berhasil; isi/koreksi hasil secara manual.'),'text'=>'');}}
  return $result;
 }
 private function target($type,$id){if($type==='spp')return $this->operations->spp->capture($id);if($type==='invoice')return $this->operations->billing->invoice($id);if($type==='bunker')return $this->operations->bunker($id);if($type==='ksop'){if(!$this->operations->billing->branches())return null;$ids=array_column($this->operations->billing->branches(),'SpbbID');return $this->db->where_in('SpbbID',$ids)->where('KsopID',(int)$id)->get('PipelineKsop')->row_array();}return null;}
 private function unused($type,$r){
  if($type==='spp'){if($this->db->table_exists('PipelineFlowRequest')&&$this->db->where('CaptureID',$r['CaptureID'])->get('PipelineFlowRequest')->row_array())throw new RuntimeException('SPP terkunci karena dipakai untuk BA Pengisian.');if($this->db->where('CaptureID',$r['CaptureID'])->get('PipelineSppInvoice')->row_array())throw new RuntimeException('SPP sudah ditagihkan. Revisi/hapus invoice terlebih dahulu.');if($r['DocumentID']||$r['DeliveryID'])throw new RuntimeException('SPP telah terhubung ke DO. Lepaskan/revisi dokumen terkait dahulu.');if($this->db->where('CaptureID',$r['CaptureID'])->get('PipelineOperation')->row_array())throw new RuntimeException('SPP sudah digunakan oleh berita acara. Revisi dokumen turunan dahulu.');}
  if($type==='bunker'){if($this->db->where('BunkerID',$r['BunkerID'])->get('PipelineKsop')->row_array()||$this->db->where('BunkerID',$r['BunkerID'])->get('PipelineOperation')->row_array())throw new RuntimeException('Permohonan sudah dipakai KSOP/berita acara. Revisi dokumen turunan dahulu.');}
  if($type==='invoice'){$q=$this->db->query("DECLARE @r int;EXEC @r=sp_getapplock @Resource=?,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=10000;SELECT @r r",array('pipeline-'.hash('sha256','payment/'.$r['InvoiceID'])));if(!$q||(int)$q->row()->r<0)throw new RuntimeException('Invoice sedang diproses.');if($this->db->where('InvoiceID',$r['InvoiceID'])->get('PipelinePayment')->row_array())throw new RuntimeException('Invoice sudah mempunyai pembayaran; tidak dapat diedit/dihapus.');}
 }
 public function edit($type,$id){$this->menu($type);$r=$this->target($type,$id);if(!$r)show_404();$error='';$form=$type==='bunker'?json_decode($r['Snapshot'],true):$r;
  if($type==='spp'){$this->load->library('Pipeline_spp_ocr');$fields=$this->pipeline_spp_ocr->fields();}elseif($type==='bunker'){$this->load->library('Pipeline_bunker_letter');$fields=$this->pipeline_bunker_letter->fields()+array('Supplier'=>array('Supplier','text',200),'Captain'=>array('Nakhoda','text',200),'Signatory'=>array('Penandatangan','text',200),'SignatoryTitle'=>array('Jabatan','text',200),'Place'=>array('Tempat Surat','text',200),'PortName'=>array('Pelabuhan','text',200),'Recipient'=>array('Tujuan Surat','textarea',500),'RecipientPlace'=>array('Kota Tujuan','text',200),'AttachmentText'=>array('Lampiran','text',100),'IssuerName'=>array('Nama Perusahaan Kop','text',200),'FooterBranch'=>array('Cabang Footer','text',200),'IssuerAddress'=>array('Alamat Footer','textarea',500),'IssuerPhone'=>array('Telepon','text',100),'IssuerWebsite'=>array('Website','text',150));}elseif($type==='ksop')$fields=array('ReferenceNo'=>array('Nomor Surat','text',100),'DocumentDate'=>array('Tanggal Surat','date',10));else $fields=array('InvoiceNumber'=>array('Nomor Invoice','text',100),'InvoiceDate'=>array('Tanggal Invoice','date',10),'DueDate'=>array('Jatuh Tempo','date',10));
  if($this->input->method()==='post'){$this->guard();$replacement=null;try{if(in_array($type,array('spp','ksop'),true))$this->unused($type,$r);$replacement=$this->replacement($type);$this->operations->transaction(function()use($type,$id,$r,$fields,$replacement){$current=$this->target($type,$id);if(!$current)throw new RuntimeException('Dokumen telah dihapus.');$this->unused($type,$current);$version=$this->input->post('RevisionHash');if(!is_string($version)||!hash_equals(hash('sha256',json_encode($current)),$version))throw new RuntimeException('Dokumen berubah. Muat ulang form.');$data=array();foreach($fields as $key=>$meta){$v=$this->input->post($key);if(!is_string($v)||mb_strlen($v)>$meta[2])throw new RuntimeException($meta[0].' tidak valid.');$data[$key]=trim($v);}
   if($type==='spp'){if($this->input->post('Confirmed')!=='1')throw new RuntimeException('Konfirmasi hasil koreksi SPP.');$data=$this->pipeline_spp_ocr->validate($data);$data+=array('OcrFieldsJson'=>json_encode($data,JSON_UNESCAPED_UNICODE),'OcrWarningsJson'=>'[]','Status'=>'CONFIRMED','ConfirmedBy'=>$this->session->userdata('MIS_LOGGED_ID'),'ConfirmedAt'=>date('Y-m-d H:i:s'),'UpdatedAt'=>date('Y-m-d H:i:s'));$table='PipelineSppCapture';$key='CaptureID';}
   elseif($type==='bunker'){$s=json_decode($current['Snapshot'],true);$data=$this->pipeline_bunker_letter->prepare($s,array_merge($s,$data));$data=array('Snapshot'=>json_encode($data,JSON_UNESCAPED_UNICODE));$table='PipelineBunker';$key='BunkerID';}
   elseif($type==='ksop'){if($data['ReferenceNo']===''||!$this->pipeline_finance->date_valid($data['DocumentDate']))throw new RuntimeException('Nomor/tanggal surat tidak valid.');$table='PipelineKsop';$key='KsopID';}
   else{if($data['InvoiceNumber']===''||!$this->pipeline_finance->date_valid($data['InvoiceDate'])||!$this->pipeline_finance->date_valid($data['DueDate'])||$data['DueDate']<$data['InvoiceDate'])throw new RuntimeException('Nomor/tanggal invoice tidak valid.');$table='PipelineInvoice';$key='InvoiceID';}
   if($replacement){$data=array_merge($data,$replacement['data']);if($type==='spp'){$ocr=$replacement['ocr'];$data=array_merge($data,$ocr['fields'],array('DensityObs'=>null,'TemperatureObs'=>null,'Status'=>'NEEDS_REVIEW','ConfirmedBy'=>null,'ConfirmedAt'=>null,'OcrText'=>$ocr['text'],'OcrFieldsJson'=>json_encode($ocr['fields'],JSON_UNESCAPED_UNICODE),'OcrWarningsJson'=>json_encode($ocr['warnings'],JSON_UNESCAPED_UNICODE)));foreach(array('OrderedLiters','DeliveryDate') as $nullable)if($data[$nullable]==='')$data[$nullable]=null;}}
   $this->operations->audit($type,$id,'EDIT',$current);if(!$this->db->where($key,(int)$id)->update($table,$data))throw new RuntimeException('Perubahan ditolak; periksa nomor duplikat.');});$this->session->set_flashdata('Berhasil','Dokumen diperbarui.');redirect($replacement&&$type==='spp'?'Pipeline_spp/review/'.$id:'Pipeline_documents/edit/'.$type.'/'.$id);return;
  }catch(Exception $e){if($replacement&&is_file($replacement['path']))unlink($replacement['path']);$error=$e->getMessage();$form=array_merge($form,array_filter($this->input->post(),'is_scalar'));}}
  $this->render('document_edit',compact('type','id','r','form','fields','error'));
 }
 public function delete($type,$id){$this->menu($type);$this->guard();try{if(in_array($type,array('BASTB','RDT','PASS'),true))$this->operations->remove((int)$id);else $this->operations->transaction(function()use($type,$id){$r=$this->target($type,$id);if(!$r)throw new RuntimeException('Dokumen tidak ditemukan.');$this->unused($type,$r);$this->operations->audit($type,$id,'DELETE',$r);$keys=array('spp'=>array('PipelineSppCapture','CaptureID'),'bunker'=>array('PipelineBunker','BunkerID'),'ksop'=>array('PipelineKsop','KsopID'),'invoice'=>array('PipelineInvoice','InvoiceID'));if($type==='invoice')foreach(array('PipelineSppInvoice','PipelineOperationInvoice','PipelineInvoiceDelivery','PipelineInvoiceLine') as $table)$this->db->where('InvoiceID',(int)$id)->delete($table);$this->db->where($keys[$type][1],(int)$id)->delete($keys[$type][0]);});$this->session->set_flashdata('Berhasil','Dokumen dihapus dari daftar; jejak audit tersimpan.');}catch(Exception $e){$this->session->set_flashdata('Gagal',$e->getMessage());}if($type==='spp' && $this->session->flashdata('Gagal')){redirect('Pipeline_documents/spp_links/'.(int)$id);return;}$links=array('spp'=>'Pipeline_spp','bunker'=>'Pipeline_setup/bunker','ksop'=>'Pipeline_setup/ksop','invoice'=>'Pipeline_billing/invoices');redirect($links[$type]??'Pipeline_documents/index/'.$type);}
}
